# Merge into single lookup
T.update(T2)


def slug_from_filename(filename):
    return filename[len("BP1-"):-len(".yaml")]


def write_sidecar(locale, bp1_filename, entries_data):
    """Emit YAML preserving the existing L1-sidecar style."""
    out_dir = os.path.join(I18N_DIR, locale, "processes")
    os.makedirs(out_dir, exist_ok=True)
    out_path = os.path.join(out_dir, bp1_filename)
    L = []
    L.append("kind: business-process")
    L.append(f"locale: {locale}")
    L.append(f"source: {bp1_filename}")
    L.append("entries:")
    for bp_id, name in entries_data:
        L.append(f"  {bp_id}:")
        # Always quote to be safe for special chars
        escaped = name.replace("\\", "\\\\").replace('"', '\\"')
        L.append(f'    name: "{escaped}"')
    with open(out_path, "w", encoding="utf-8") as f:
        f.write("\n".join(L) + "\n")


def main():
    missing = set()
    written = 0
    for path in sorted(os.listdir(PROCESSES_DIR)):
        if not (path.startswith("BP1-") and path.endswith(".yaml")):
            continue
        with open(os.path.join(PROCESSES_DIR, path)) as f:
            tree = yaml.safe_load(f)
        # Collect (id, en_name) pairs for BP1 + BP2 only
        pairs_en = [(tree["id"], tree["name"])]
        for bp2 in tree.get("children") or []:
            pairs_en.append((bp2["id"], bp2["name"]))
        # Verify all names have translations
        for _, en_name in pairs_en:
            if en_name not in T:
                missing.add(en_name)
        if missing:
            continue  # Skip writing until we have full coverage
        for locale in LOCALES:
            entries = [(bp_id, T[en_name][locale]) for (bp_id, en_name) in pairs_en]
            write_sidecar(locale, path, entries)
            written += 1
    if missing:
        print(f"⚠ MISSING translations for {len(missing)} names:")
        for n in sorted(missing): print(f"   - {n}")
        return 1
    print(f"✔ Wrote {written} sidecar files across {len(LOCALES)} locales")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
